const clean=value=>String(value??"").replace(/\s+/g," ").trim();
const cookie=name=>document.cookie.split(";").map(x=>x.trim()).find(x=>x.startsWith(name+"="))?.slice(name.length+1)??"";
window.ox.install(({action})=>{
  const memberKey=()=>{const raw=cookie("pbcMemberKeys");if(!raw)throw new Error("Premera member context is unavailable. Sign in to Premera and retry.");let parsed;try{parsed=JSON.parse(decodeURIComponent(raw));}catch{throw new Error("Premera member context is malformed.");}const registrations=Array.isArray(parsed?.registrations)?parsed.registrations:[];const selected=registrations.filter(x=>x?.isSelected===true);const item=selected.length===1?selected[0]:registrations.length===1?registrations[0]:null;const key=String(item?.memberKey??"");if(!/^\d+$/.test(key))throw new Error("Premera has no unique selected member plan.");return key;};
  const request=async(path,init={})=>{const response=await fetch("https://member-edge.premera.com"+path,{credentials:"include",cache:"no-store",...init});const text=await response.text();if(response.status===401)throw new Error("Premera sign-in is required.");if(!response.ok)throw new Error(path+": Premera request failed (HTTP "+response.status+").");try{return JSON.parse(text);}catch{throw new Error(path+": Premera returned malformed data.");}};
  const post=(path,body)=>request(path,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});
  const signInState=async()=>{const r=await fetch("https://member-edge.premera.com/api/v2.0/Member/registrationdetails",{method:"POST",credentials:"include",cache:"no-store",headers:{"Content-Type":"application/json"},body:"{}"});const text=await r.text();if(r.status===401&&text==="")return false;if(r.status===400){let body;try{body=JSON.parse(text);}catch{throw new Error("Premera returned malformed sign-in state.");}if(body?.errors?.RequestorMemberKey?.includes("The RequestorMemberKey field is required."))return true;}throw new Error("Premera returned an unsupported sign-in state (HTTP "+r.status+").");};
  action("getSignInUrl",{async invoke(){return{url:"https://myaccount.premera.com/"};}});
  action("getSignInState",{async invoke(){return{signedIn:await signInState()};}});
  action("getCoverageSummary",{async invoke(){const key=memberKey();const [registration,accumulators]=await Promise.all([post("/api/v2.0/Member/registrationdetails",{requestorMemberKey:key,memberKeys:[key]}),post("/api/v1.0/benefits/accumulators",{requestorMemberKey:key,targetMemberKey:key,productCategory:"M",asOfDate:new Date().toISOString()})]);const plan=registration?.result?.find?.(x=>String(x.memberKey)===key)??registration?.result?.[0];const network=accumulators?.result?.find?.(x=>x.networkType==="In Network")??accumulators?.result?.[0];const individual=Array.isArray(network?.individualAccumulators)?network.individualAccumulators:[],familyItems=Array.isArray(network?.familyAccumulators)?network.familyAccumulators:[];const convert=x=>x?{maximum:Number(x.maxAmount),paid:Number(x.usedAmount),remaining:Number(x.remainingAmount)}:null;const deductible=convert(individual.find(x=>x.accumulatorType==="Deductible")),oop=convert(individual.find(x=>x.accumulatorType==="OOP")),family=convert(familyItems.find(x=>x.accumulatorType==="OOP"));if(!plan||!deductible||!oop)throw new Error("Premera returned an unsupported coverage summary.");return{planName:clean(plan.groupName),status:clean(plan.planStatus).toLowerCase(),deductible,individualOutOfPocket:oop,familyOutOfPocket:family,resetDate:network?.planRenewalDate?String(network.planRenewalDate).slice(0,10):null,currency:"USD",sourceUrl:"https://member.premera.com/dashboard"};}});
  action("getPersonalInfo",{async invoke(){const key=memberKey();const [details,contact,eob,registration,survey]=await Promise.all([request("/api/v2.0/Member/details?requestorMemberKey="+encodeURIComponent(key)),post("/api/v1.0/contactdetails/contactdetails",{requestorMemberKey:key,targetMemberKey:key}),request("/api/v1.0/members/eob/preference/get?memberKey="+encodeURIComponent(key),{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"}),post("/api/v2.0/Member/registrationdetails",{requestorMemberKey:key,memberKeys:[key]}),post("/api/v1.0/relsurvey/getSurvey",{memberKey:key})]);const person=details?.result?.data?.find?.(x=>String(x.memberKey)===key)??details?.result?.data?.[0],address=contact?.result,preference=eob?.result?.data,plan=registration?.result?.find?.(x=>String(x.memberKey)===key)??registration?.result?.[0],surveyMember=survey?.result?.data?.members?.find?.(x=>String(x.memberKey)===key);if(!person||!address||!preference)throw new Error("Premera returned an unsupported personal-information response.");const phone=String(address.phoneNumber??"").replace(/^(\d{3})(\d{3})(\d{4})$/,"($1) $2-$3");const city=[address.city,address.state,address.zipCode].filter(Boolean).join(" ");const questionnaire=Array.isArray(surveyMember?.responses)&&surveyMember.responses.length>0?"started":"Not started";return{name:clean(person.firstName+" "+person.lastName).replace(/\b\w/g,c=>c.toUpperCase()),dateOfBirth:String(person.dateOfBirth??"").slice(0,10),streetAddress:clean([address.addressLine1,address.addressLine2].filter(Boolean).join(" ")),cityStatePostalCode:clean(city),phone,accountEmail:String(preference.email??""),planName:plan?clean(plan.groupName):null,planStatus:plan?clean(plan.planStatus).toLowerCase():null,paperlessEob:preference.preference===true,demographicQuestionnaireStatus:questionnaire,addressUpdateNote:"Contact your benefit administrator or employer to update your address.",sourceUrl:"https://member.premera.com/account-settings"};}});
  action("listRecentClaims",{async invoke(){const key=memberKey(),end=new Date(),start=new Date(end);start.setUTCFullYear(start.getUTCFullYear()-3);const data=await post("/api/v1.0/claims/",{requestorMemberKey:key,claimSearchEndDate:end.toISOString(),claimSearchStartDate:start.toISOString(),claimStatus:"",claimType:"",paging:{totalNumberOfResults:0,pageNumber:1,resultsPerPage:3},targetMemberKey:""});const rows=data?.result?.claimsResults;if(!Array.isArray(rows))throw new Error("Premera returned an unsupported claims response.");const items=rows.slice(0,3).map(row=>({serviceDate:String(row.serviceStartDate??"").slice(0,10),provider:clean(row.providerName),status:row.claimStatus==="C"?"Processed":clean(row.claimStatus||"Unknown"),memberResponsibility:Number(row.totalLiabilityAmount??0),currency:"USD"}));return{items,complete:Number(data?.result?.totalNumberOfResults??items.length)<=items.length,sourceUrl:"https://member.premera.com/dashboard"};}});
});
